SELECT 
FROM account_details ad
LEFT JOIN agents a ON ad.agent_id = a.id
WHERE 1=1

    AND ad.agent_id = #{agentId}


    AND ad.type = #{type}


    AND ad.create_time >= #{startTime}


    AND ad.create_time <= #{endTime}

ORDER BY ad.create_time DESC

SELECT 
FROM account_details ad
LEFT JOIN agents a ON ad.agent_id = a.id
WHERE ad.agent_id = #{agentId}
ORDER BY ad.create_time DESC
LIMIT #{offset}, #{size}
